sql:
SELECT SUM(execucao_mensal.valor_pago) AS total_pagamento_saude
FROM execucao_mensal
JOIN orgao ON execucao_mensal.codigo_orgao = orgao.codigo
WHERE orgao.nome_orgao_superior = 'Ministério da Saúde' AND execucao_mensal.ano = 2025;

DROP TABLE orcamento;

